-- Passage rg11-main-idea-summary-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('11940ca5-259d-5c38-9ece-ea1fc10e8679', 'rg11-main-idea-summary-p01', (select id from public.skills where slug = 'read-g11-main-idea-summary'), null,
        '9-12', $q$Reading the Air in Lichen$q$, $q$On the stone walls and tree bark of almost any town, small crusty patches of gray, green or orange grow so slowly that most people never notice them. These are lichens, partnerships between a fungus and a partner that makes food from sunlight, usually an alga. The fungus builds the body and gathers moisture, while the partner supplies sugars. Because neither depends on soil, lichens can live on bare rock, rooftops and fence posts.

That same independence makes lichens unusually sensitive to the air around them. A lichen has no roots and no waxy outer layer to protect it. It absorbs water and dissolved minerals directly from rain, fog and dust, and it takes in whatever pollutants come along with them. Some kinds tolerate polluted air well, but others decline quickly when sulfur or nitrogen compounds build up.

Scientists have turned this weakness into a tool. By recording which lichen species grow in a place, and how large and healthy they are, researchers can estimate the quality of the air over many years, something a single day of instrument readings cannot show. In a survey in the fictional river city of Dunmore, volunteers mapped lichens on two hundred trees. Leafy and bushy lichens were common in parks far from the highway but almost absent along the busiest roads, where only flat, crusty species survived.

Lichen surveys do not replace air monitors. They cannot measure the exact amount of a specific pollutant, and a dry summer or a shady site can also change what grows. Yet they are inexpensive, they cover large areas, and they record conditions over long periods. For cities that cannot afford monitoring stations on every street, the patches on a tree trunk offer a living record that anyone trained to read them can use.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
