  ('6f4e8c03-c364-51bf-9336-e1a597e486b7', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'medium',
   $q$Which choice is the best objective summary of the poem?$q$, $q$[{"text":"A speaker complains about hiking each August with an aunt who cares more about a notebook than about her family.","is_correct":false,"misconception_token":"includes-opinion"},{"text":"A speaker helps an aunt measure a shrinking glacier each year, comes to see the record as a way of paying attention, and plans to continue the work.","is_correct":true},{"text":"A speaker and an aunt discover that the glacier has started growing again after many years.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"A speaker hears meltwater running under the stones and compares the ice to someone standing up.","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$A speaker helps an aunt measure a shrinking glacier each year, comes to see the record as a way of paying attention, and plans to continue the work.$q$, $q$The correct choice covers the yearly measuring, the speaker's changed view, and the plan to carry the stakes. The meltwater choice describes only one stanza, and the glacier is shrinking, not growing.$q$, 'draft', '5014dedd-4788-5a9b-815f-3c11a732119c')
