  ('a5c65725-2630-5ea4-ad47-3361b75f42e5', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"Cross-country courses with steep hills are harder than flat ones.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Runners should always slow down to help their rivals during a race.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"A meaningful achievement can come from how we treat others, not only from the numbers we reach.","is_correct":true},{"text":"Rivals can never become friends because competition divides people.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$A meaningful achievement can come from how we treat others, not only from the numbers we reach.$q$, $q$Priya misses her time but gains a connection she records as worth remembering. The "always slow down" choice turns one choice in the story into a rule the passage never states.$q$, 'draft', '84cd6bc4-cabe-557e-b99a-2929b048090e')
