  ('042ef92e-dee0-54b9-ad4b-427a331c8a43', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'hard',
   $q$How does the repetition of "Checked this week" at the end develop the theme?$q$, $q$[{"text":"Orrin's fine engraving now carries Liesl's humble practice, showing that skill and willingness to revise must work together.","is_correct":true},{"text":"It reveals that the river moves every week, so maps are useless after seven days.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It shows that Orrin has copied Liesl's maps and now sells them as his own work.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests that Orrin's maps are now just as rough and inelegant as Liesl's.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Orrin's fine engraving now carries Liesl's humble practice, showing that skill and willingness to revise must work together.$q$, $q$The plain line sits "beneath the fine engraving," combining Orrin's craft with the habit of checking. The engraving remains fine, so his maps have not become rough.$q$, 'draft', 'bab7329c-41a8-5098-83e6-e160f484dcd1')
