  ('e7fa368c-504b-55ed-8983-2e03418b56cf', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'hard',
   $q$Why is it significant that a child, rather than an angry traveler, finally causes Orrin to change?$q$, $q$[{"text":"Her simple eyewitness statement offers no argument to resist, so Orrin must face the evidence itself.","is_correct":true},{"text":"It shows that Orrin only listens to people younger than his former apprentice.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The child is secretly Liesl's daughter, sent to teach Orrin a lesson.","is_correct":false,"misconception_token":"adds-false-detail"},{"text":"The child threatens to buy her maps from Liesl unless Orrin fixes his work.","is_correct":false,"misconception_token":"adds-false-detail"}]$q$::jsonb, $q$Her simple eyewitness statement offers no argument to resist, so Orrin must face the evidence itself.$q$, $q$The child just says "I watched it go," and Orrin then looks at his map "for a long while" before measuring. She makes no threat; the change comes from the plain fact she reports.$q$, 'draft', 'bab7329c-41a8-5098-83e6-e160f484dcd1')
