  ('2acc2a23-8098-50dd-86d2-3fc312b255ec', null, (select id from public.skills where slug = 'read-g12-argument-evidence'), null, 'hard',
   $q$Why is the Gresham Valley example weak support for the claim that a trail would bring business?$q$, $q$[{"text":"Gresham Valley is a much larger place than Hallam or Ashby Mills.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Three new cafes do not show the trail caused them or that trade grew overall.","is_correct":true},{"text":"The Gresham Valley trail has been open for only four years.","is_correct":false,"misconception_token":"misidentifies-flaw"},{"text":"Cafes are a kind of business that trail users rarely visit.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Three new cafes do not show the trail caused them or that trade grew overall.$q$, $q$The writer gives no evidence that the trail drew the cafes or that other businesses did not close, so the example shows timing, not cause. The passage says nothing about Gresham Valley's size, so that choice relies on outside assumptions.$q$, 'draft', '4edd66d6-6d04-5b9f-bb6a-423afcb39df1')
