  ('bafe21da-17c3-51f3-9696-d334ec63e770', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'medium',
   $q$What purpose does the detail about the Dunmore watchmaker's clock with two minute hands serve?$q$, $q$[{"text":"It explains the mechanical design of clocks that were common in the valley's largest town.","is_correct":false,"misconception_token":"too-narrow"},{"text":"It shows that watchmakers profited from confusion and opposed the railway's new valley time.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It offers concrete evidence that residents actively lived with and compared both time systems.","is_correct":true},{"text":"It proves that railway time was less accurate than town time and could not be trusted.","is_correct":false,"misconception_token":"overstates-claim"}]$q$::jsonb, $q$It offers concrete evidence that residents actively lived with and compared both time systems.$q$, $q$Customers coming "from miles away to check it" shows people working out how to live with two times, which supports her "busier story." Nothing says the watchmaker opposed the railway or that either time was inaccurate.$q$, 'draft', 'a10f0fdd-fb91-54a2-8706-60ff47a4f21d')
