values
  ('227888ae-c84c-50a3-8db1-724cd3e6d82d', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'hard',
   $q$Why is it rhetorically useful for the speaker to say early on, "I am not here to talk anyone out of the violin"?$q$, $q$[{"text":"It shows that she is a violin teacher herself and is only promoting the bassoon because the orchestra requires it.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It admits that her argument is weak, which lowers families' expectations before she describes the bassoon's features.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"It tells families that the violin line is closed, so they have no choice but to consider the other instruments.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It eases the defensiveness of families already set on the violin, so her appeal sounds like an invitation rather than an attack.","is_correct":true}]$q$::jsonb, $q$It eases the defensiveness of families already set on the violin, so her appeal sounds like an invitation rather than an attack.$q$, $q$Many listeners are standing in the violin line, so praising the violin as "glorious" keeps them listening, and her closing "I invite you" fits that friendly stance. Nothing suggests she teaches violin or that the violin line is closed.$q$, 'draft', 'ca2f3581-9821-590e-a114-8dc8d2fb1fb1')
