  ('276aefff-4b6e-55d6-8cf1-ec795ac339af', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'medium',
   $q$What does the comparison "closer to editing a poem under a stopwatch" suggest about subtitling?$q$, $q$[{"text":"It is simpler than translation, since a subtitler only needs to shorten what has already been written.","is_correct":false,"misconception_token":"reverses-viewpoint"},{"text":"It is a race in which subtitlers compete to finish translating a film faster than their colleagues.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It demands both an artist's precision with words and the ability to work within strict limits of time.","is_correct":true},{"text":"It mainly involves turning the dialogue of films into rhyming verse that viewers can memorize easily.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$It demands both an artist's precision with words and the ability to work within strict limits of time.$q$, $q$"Poem" points to careful choices about every word, and "stopwatch" points to the reading-speed limit he explains next. He presents subtitling as harder than viewers assume, not simpler.$q$, 'draft', 'd8a9442f-b290-54dc-a716-2fe6a10d69f9')
