  ('366f670d-3897-5ceb-8a9e-df990a3446f4', null, (select id from public.skills where slug = 'read-g12-character-setting-plot'), null, 'hard',
   $q$Why is it significant that the speaker uses the chalk from the third stanza to mark a straight hem line in the door frame?$q$, $q$[{"text":"It proves that she resents the landlord and wants to damage the property before leaving.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It marks the height she was as a child so the new tenant will know who once lived there.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows that she intends to return and reopen the shop after the new tenant leaves.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It echoes his lesson to \"stand straight,\" so she leaves his teaching hidden inside the setting that is being taken away.","is_correct":true}]$q$::jsonb, $q$It echoes his lesson to "stand straight," so she leaves his teaching hidden inside the setting that is being taken away.$q$, $q$The chalk carries the memory of his instruction, and marking "straight, the way he taught me" in a hidden spot preserves him in the place itself. She chooses a spot "where no one cleaning will think to look," so it is not meant for the tenant to see.$q$, 'draft', '2197d1eb-c5c8-5df6-85e4-fdbb2eed36e9')
