values
  ('e7b5b6f5-7eeb-50e6-b27f-775d78125e26', null, (select id from public.skills where slug = 'read-g12-character-setting-plot'), null, 'medium',
   $q$What is the effect of introducing Mrs. Odunsi through her thirty-one years of bus driving and her single quilt?$q$, $q$[{"text":"It shows that she is new to chess and is likely to lose quickly to an experienced player.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It reveals that she and Mr. Baptiste are old friends who share the club's strict rules.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It explains why she is in a hurry and wants the game to end as soon as possible.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It suggests patience and steady habit, and the quilt detail sets up the move that turns the plot.","is_correct":true}]$q$::jsonb, $q$It suggests patience and steady habit, and the quilt detail sets up the move that turns the plot.$q$, $q$Decades on one route hint at a steady, patient person, and the forty-minute quilt is the very load she later pulls out early. She is not in a hurry; she gives up the dryer's timer.$q$, 'draft', 'abf12121-e77a-5ab8-8b6e-30491211e8f8')
